import React from 'react';
import { useLocation, useNavigate, Navigate } from 'react-router-dom';
import './AptitudeTest.css'; // Reusing the result styles from here, or we can split it

const AptitudeResults = () => {
    const location = useLocation();
    const navigate = useNavigate();

    // Check if result data was passed via router state
    const result = location.state?.result;

    if (!result) {
        // If someone navigates to /aptitude-results directly without taking a test
        return <Navigate to="/aptitude-test" replace />;
    }

    const handleGetRecommendations = () => {
        // Here we could navigate to a new recommendations page, passing the strengths
        // navigate('/recommendations', { state: { strength: result.strength_category }});
        alert('Career recommendations feature coming next!');
    };

    return (
        <div className="test-results-container">
            <h2>Quiz Results</h2>
            <div className="result-card">
                <div className="score-circle">
                    <span>{result.score}/{result.total_questions}</span>
                    <p>{result.percentage}</p>
                </div>

                <div className="category-insights">
                    <div className="insight strength">
                        <h3>🌟 Top Strength</h3>
                        <p>{result.strength_category || 'N/A'}</p>
                    </div>
                    <div className="insight weakness">
                        <h3>🎯 Area to Improve</h3>
                        <p>{result.weak_category || 'N/A'}</p>
                    </div>
                </div>

                <div className="breakdown">
                    <h3>Detailed Breakdown</h3>
                    {Object.entries(result.category_breakdown).map(([cat, stats]) => (
                        <div key={cat} className="breakdown-item">
                            <span>{cat}</span>
                            <div className="progress-bg">
                                <div
                                    className="progress-fill"
                                    style={{ width: `${(stats.correct / stats.total) * 100}%` }}
                                ></div>
                            </div>
                            <span>{stats.correct}/{stats.total}</span>
                        </div>
                    ))}
                </div>

                <div className="result-actions" style={{ display: 'flex', gap: '15px', justifyContent: 'center', marginTop: '20px' }}>
                    <button className="btn-secondary" onClick={() => navigate('/dashboard')}>
                        Go to Dashboard
                    </button>
                    <button className="btn-primary" onClick={handleGetRecommendations}>
                        Get Career Recommendations
                    </button>
                </div>
            </div>
        </div>
    );
};

export default AptitudeResults;
